events = [
    {"event_id": "a", "region": "east", "amount": 4},
    {"event_id": "b", "region": "west", "amount": 9},
    {"event_id": "a", "region": "east", "amount": 4},
]
seen = {}
for event in events:
    seen.setdefault(event["event_id"], event)
totals = {}
for event in seen.values():
    totals[event["region"]] = totals.get(event["region"], 0) + event["amount"]
print(totals)
